CREATE TABLE IF NOT EXISTS examinations (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL, exam_type TEXT NOT NULL, academic_year_id TEXT REFERENCES academic_years(id), term_id TEXT REFERENCES terms(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS examination_subjects (id TEXT PRIMARY KEY, examination_id TEXT NOT NULL REFERENCES examinations(id), subject_id TEXT NOT NULL REFERENCES subjects(id), max_marks REAL NOT NULL DEFAULT 100, weight REAL NOT NULL DEFAULT 100);
CREATE TABLE IF NOT EXISTS examination_candidates (id TEXT PRIMARY KEY, examination_id TEXT NOT NULL REFERENCES examinations(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), UNIQUE(examination_id, student_id));
CREATE TABLE IF NOT EXISTS examination_timetable (id TEXT PRIMARY KEY, examination_id TEXT NOT NULL REFERENCES examinations(id), subject_id TEXT REFERENCES subjects(id), room TEXT, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, invigilator_id TEXT REFERENCES staff(id));
CREATE TABLE IF NOT EXISTS grading_systems (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL, boundaries_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS examination_marks (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), examination_id TEXT NOT NULL REFERENCES examinations(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), subject_id TEXT NOT NULL REFERENCES subjects(id), raw_marks REAL NOT NULL, weight REAL NOT NULL, weighted_marks REAL NOT NULL, grade TEXT NOT NULL, comment TEXT, state TEXT NOT NULL DEFAULT 'DRAFT', version INTEGER NOT NULL DEFAULT 1, entered_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL, UNIQUE(examination_id, student_id, subject_id));
CREATE TABLE IF NOT EXISTS promotion_decisions (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), academic_year_id TEXT NOT NULL REFERENCES academic_years(id), decision TEXT NOT NULL, comment TEXT, decided_by TEXT NOT NULL REFERENCES users(id), decided_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS external_exam_records (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), exam_name TEXT NOT NULL, candidate_number TEXT, subjects_json TEXT, preparation_notes TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_exam_marks_student ON examination_marks(school_id, student_id, examination_id);
CREATE INDEX IF NOT EXISTS idx_exam_marks_state ON examination_marks(school_id, state);
